function home(){return `${topbar('home')}<main class="heritage-home"><section class="home-hero"><div class="hero-text"><div class="micro heritage-eyebrow">SEKEPING.MY · STUDIO KENANGAN MAJLIS</div><h1 class="serif">Kenangan yang<br><i>kekal</i> selamanya.</h1><div class="heritage-divider" aria-hidden="true"><span></span><i>✦</i><span></span></div><p>Satu ruang istimewa untuk tetamu merakam foto, menitip suara dan mengirim doa. Diabadikan dengan indah untuk hari yang takkan berulang.</p><div class="actions hero-buttons"><a class="btn" data-nav="dashboard" href="${dashboardUrl(false)}">Cipta Majlis ${icon('arrow','sm')}</a><a class="btn secondary" data-nav="demo" href="${eventUrl('demo',true)}">Terokai Demo ${icon('eye','sm')}</a></div><p class="home-note">Hanya imbas kod QR. Tiada aplikasi tambahan.</p></div><div class="hero-stage" aria-label="Ilustrasi album kenangan klasik"><div class="heritage-photo-deck"><div class="heritage-photo-back" aria-hidden="true"></div><div class="heritage-photo-front"><div class="heritage-photo-art"><span class="heritage-sun"></span><span class="heritage-mountain one"></span><span class="heritage-mountain two"></span><span class="heritage-sprig"></span></div><span class="heritage-photo-inscription">a little moment, a lifetime memory</span></div><div class="heritage-deck-seal" aria-hidden="true">S<span>.</span></div></div></div></section><section class="feature-band"><div class="feature-grid"><div class="feature"><span class="feature-icon">${icon('camera','big')}</span><div><h4>Fotografi Klasik</h4><p>Filter analog, grain & vignette.</p></div></div><div class="feature"><span class="feature-icon">${icon('mic','big')}</span><div><h4>Pesanan Suara</h4><p>Suara tulus untuk dikenang.</p></div></div><div class="feature"><span class="feature-icon">${icon('qr','big')}</span><div><h4>Kad QR Eksklusif</h4><p>Poster A5 dengan corak warisan.</p></div></div></div></section><section class="home-end"><div class="micro heritage-eyebrow">SETIAP DETIK PUNYA CERITA</div><h2 class="serif">Yang indah, kita simpan bersama.</h2><p>Abadikan hari istimewa dalam satu album digital.</p><a class="btn" href="${eventUrl('demo',true)}" data-nav="demo">Lihat Laman Tetamu ${icon('arrow','sm')}</a></section></main>${footer()}`}
function coverVisual(v,kind='guest'){
 const url=v.coverDisplay||v.coverUrl||'';if(!url)return '<div class="cover-art-fallback"></div>';
 const fit=v.coverFit==='contain'?'contain':'cover';const zoom=Math.max(1,Math.min(2.5,(Number(v.coverZoom)||100)/100));const x=Number.isFinite(Number(v.coverX))?Number(v.coverX):50,y=Number.isFinite(Number(v.coverY))?Number(v.coverY):50;
 return `<span class="cover-blurred-backdrop" aria-hidden="true" style="background-image:url('${e(url)}')"></span><img class="cover-foreground ${fit==='contain'?'fit-contain':'fit-cover'}" src="${e(url)}" alt="Gambar pasangan pengantin" style="object-position:${x}% ${y}%;transform:scale(${zoom})">`;
}
