function selectedCoverData(){return {coverFit:document.querySelector('input[name="coverFit"]:checked')?.value||'cover',coverZoom:Number(document.querySelector('#coverZoom')?.value||100),coverX:Number(document.querySelector('#coverX')?.value||50),coverY:Number(document.querySelector('#coverY')?.value||50),theme:document.querySelector('#themeInput')?.value||'#254b42'}}
